func binarySearchSteps(_ target: Int) -> Int {
    var low = 0
    var high = 15
    var steps = 0
    while low <= high {
        steps += 1
        let mid = (low + high) / 2
        if mid == target {
            break
        } else if mid < target {
            low = mid + 1
        } else {
            high = mid - 1
        }
    }
    return steps
}
print(binarySearchSteps(12))

func computeSum(_ arr: [Int]) -> Int {
    var sum = 0
    for x in arr {
        sum += x
    }
    return sum
}
print(computeSum([10, 20, 30]))

func countLevels(_ k: Int) -> Int {
    if k <= 1 {
        return 1
    }
    return 1 + countLevels(k - 1)
}
print(countLevels(4))

