func linearContains(_ array: [Int], target: Int) -> Bool {
    for element in array {
        if element == target {
            return true
        }
    }
    return false
}
print(linearContains([10, 20, 30], target: 20))

func hasDuplicates(_ array: [Int]) -> Bool {
    var seen = Set<Int>()
    for element in array {
        if seen.contains(element) {
            return true
        }
        seen.insert(element)
    }
    return false
}
print(hasDuplicates([1, 2, 3, 2]))

func makeSquares(_ array: [Int]) -> [Int] {
    var result: [Int] = []
    result.reserveCapacity(array.count)
    for element in array {
        result.append(element * element)
    }
    return result
}
print(makeSquares([2, 3, 4]))
